// Tiny additive synthesiser + mixer. Everything is generated by code: royalty-free by construction.
// Extracted from the original Céleste Corp soundtrack script and made reusable.
import fs from "node:fs";
import path from "node:path";

const TAU = Math.PI * 2;
export const SR = 44100;
export const hz = (midi) => 440 * Math.pow(2, (midi - 69) / 12);

export function createSynth(durationSec, seedValue = 1234567) {
  const N = Math.ceil(SR * durationSec);
  const L = new Float32Array(N);
  const R = new Float32Array(N);
  const SL = new Float32Array(N); // reverb / delay send
  const SR_ = new Float32Array(N);
  let seed = seedValue | 0 || 1;
  const rnd = () => {
    seed ^= seed << 13;
    seed ^= seed >>> 17;
    seed ^= seed << 5;
    return ((seed >>> 0) / 4294967296) * 2 - 1;
  };

  const put = (i, v, pan = 0, send = 0) => {
    if (i < 0 || i >= N) return;
    const l = v * Math.cos(((pan + 1) * Math.PI) / 4);
    const r = v * Math.sin(((pan + 1) * Math.PI) / 4);
    L[i] += l;
    R[i] += r;
    if (send) {
      SL[i] += l * send;
      SR_[i] += r * send;
    }
  };
  const at = (t) => Math.floor(t * SR);

  const api = {
    N,
    kick(t, g = 0.9) {
      const s0 = at(t);
      const len = Math.floor(0.38 * SR);
      let ph = 0;
      for (let k = 0; k < len; k++) {
        const tt = k / SR;
        ph += (TAU * (48 + 120 * Math.exp(-tt * 28))) / SR;
        put(s0 + k, (Math.sin(ph) * Math.exp(-tt * 9) + (k < 120 ? rnd() * 0.25 : 0)) * g);
      }
    },
    clap(t, g = 0.5) {
      const s0 = at(t);
      const len = Math.floor(0.22 * SR);
      let prev = 0;
      for (let k = 0; k < len; k++) {
        const tt = k / SR;
        const n = rnd();
        const hp = n - prev * 0.6;
        prev = n;
        put(s0 + k, hp * Math.exp(-tt * 20) * (1 + 0.8 * Math.exp(-((tt * 1000) % 12))) * g * 0.5, 0.05, 0.12);
      }
    },
    hat(t, g = 0.18, open = false) {
      const s0 = at(t);
      const len = Math.floor((open ? 0.16 : 0.05) * SR);
      let prev = 0;
      for (let k = 0; k < len; k++) {
        const n = rnd();
        const hp = n - prev;
        prev = n;
        put(s0 + k, hp * Math.exp((-k / SR) * (open ? 22 : 70)) * g * 0.6, 0.25);
      }
    },
    bass(t, dur, midi, g = 0.3) {
      const s0 = at(t);
      const len = Math.floor((dur + 0.1) * SR);
      const f = hz(midi);
      for (let k = 0; k < len; k++) {
        const tt = k / SR;
        const env = Math.min(1, tt / 0.01) * Math.exp(-tt * 3) * (tt < dur ? 1 : Math.max(0, 1 - (tt - dur) / 0.1));
        put(s0 + k, (Math.sin(TAU * f * tt) + 0.45 * Math.sin(TAU * 2 * f * tt) + 0.2 * Math.sin(TAU * 3 * f * tt)) * env * g);
      }
    },
    pad(t, dur, midis, g = 0.07, bright = 5) {
      const s0 = at(t);
      const attack = Math.min(0.7, dur * 0.4);
      const release = 0.9;
      const len = Math.floor((dur + release) * SR);
      for (const m of midis) {
        const f = hz(m);
        for (let k = 0; k < len; k++) {
          const tt = k / SR;
          const env = Math.min(1, tt / attack) * (tt < dur ? 1 : Math.max(0, 1 - (tt - dur) / release));
          let v = 0;
          for (let h = 1; h <= bright; h++) v += (Math.sin(TAU * f * h * tt * 1.003) + Math.sin(TAU * f * h * tt * 0.997)) / (h * h * 0.7);
          put(s0 + k, v * env * g * (0.85 + 0.15 * Math.sin(TAU * 0.25 * tt + m)), Math.sin(m) * 0.5, 0.35);
        }
      }
    },
    pluck(t, midi, g = 0.14, pan = 0) {
      const s0 = at(t);
      const len = Math.floor(0.55 * SR);
      const f = hz(midi);
      for (let k = 0; k < len; k++) {
        const tt = k / SR;
        const env = Math.min(1, tt / 0.004) * Math.exp(-tt * 9);
        const v = Math.sin(TAU * f * tt) + 0.5 * Math.sin(TAU * 2 * f * tt) * Math.exp(-tt * 14) + 0.25 * Math.sin(TAU * 3 * f * tt) * Math.exp(-tt * 20);
        put(s0 + k, v * env * g, pan, 0.55);
      }
    },
    bell(t, midi, g = 0.14, decay = 2.4, pan = 0) {
      const s0 = at(t);
      const len = Math.floor(decay * 1.6 * SR);
      const f = hz(midi);
      const partials = [[1, 1], [2.76, 0.5], [5.4, 0.25], [8.93, 0.12]];
      for (let k = 0; k < len; k++) {
        const tt = k / SR;
        let v = 0;
        for (const [r, a] of partials) v += Math.sin(TAU * f * r * tt) * a * Math.exp(((-tt * (1.6 + r)) / decay) * 2);
        put(s0 + k, v * Math.min(1, tt / 0.002) * g, pan, 0.6);
      }
    },
    click(t, g = 0.22, f = 1900) {
      const s0 = at(t);
      const len = Math.floor(0.05 * SR);
      for (let k = 0; k < len; k++) {
        const tt = k / SR;
        put(s0 + k, (Math.sin(TAU * f * tt) * 0.8 + rnd() * 0.2) * Math.exp(-tt * 110) * g, 0.1, 0.15);
      }
    },
    tick(t, midi, g = 0.1, pan = 0) {
      const s0 = at(t);
      const len = Math.floor(0.14 * SR);
      const f = hz(midi);
      for (let k = 0; k < len; k++) {
        const tt = k / SR;
        put(s0 + k, Math.sin(TAU * f * tt) * Math.exp(-tt * 38) * g, pan, 0.4);
      }
    },
    /** Filtered-noise sweep. dir = +1 rising (riser), -1 falling (whoosh). */
    sweep(t, dur, dir = 1, g = 0.3, fLo = 200, fHi = 9000) {
      const s0 = at(t);
      const len = Math.floor(dur * SR);
      let y1 = 0;
      let y2 = 0;
      for (let k = 0; k < len; k++) {
        const p = k / len;
        const q = dir > 0 ? p : 1 - p;
        const a = 1 - Math.exp((-TAU * fLo * Math.pow(fHi / fLo, q * q)) / SR);
        y1 += a * (rnd() - y1);
        y2 += a * (y1 - y2);
        const env = dir > 0 ? Math.pow(p, 1.6) : Math.sin(Math.PI * Math.min(1, p * 1.2)) * (1 - p);
        put(s0 + k, y2 * env * g * 2.4, Math.sin(p * 6) * 0.5, 0.3);
      }
    },
    boom(t, g = 0.8, len2 = 1.3) {
      const s0 = at(t);
      const len = Math.floor(len2 * SR);
      let ph = 0;
      let y = 0;
      for (let k = 0; k < len; k++) {
        const tt = k / SR;
        ph += (TAU * (32 + 90 * Math.exp(-tt * 9))) / SR;
        y += 0.08 * (rnd() - y);
        put(s0 + k, (Math.sin(ph) * Math.exp(-tt * 3.2) + y * Math.exp(-tt * 9) * 1.5) * g, 0, 0.25);
      }
    },
    zap(t, g = 0.14) {
      const s0 = at(t);
      const len = Math.floor(0.09 * SR);
      let ph = 0;
      for (let k = 0; k < len; k++) {
        const tt = k / SR;
        ph += (TAU * (2600 - 22000 * tt)) / SR;
        put(s0 + k, Math.sign(Math.sin(ph)) * Math.exp(-tt * 30) * g, rnd() * 0.6);
      }
    },

    /** Reverb + ping-pong delay on the send bus, master fade, soft clip, normalise, 16-bit WAV. */
    render(file, { fadeInSec = 0.01, fadeOutSec = 1.2, peakTarget = 0.89, bpm = 120 } = {}) {
      const comb = (input, delay, fb) => {
        const d = Math.floor(delay * SR);
        const out = new Float32Array(input.length);
        for (let i = 0; i < input.length; i++) out[i] = input[i] + (i >= d ? out[i - d] * fb : 0);
        return out;
      };
      const allpass = (input, delay, g) => {
        const d = Math.floor(delay * SR);
        const out = new Float32Array(input.length);
        for (let i = 0; i < input.length; i++) {
          const del = i >= d ? out[i - d] : 0;
          const xd = i >= d ? input[i - d] : 0;
          out[i] = -g * input[i] + xd + g * del;
        }
        return out;
      };
      const reverb = (src, tweak) => {
        const sum = new Float32Array(src.length);
        [0.0297, 0.0371, 0.0411, 0.0437].forEach((d, i) => {
          const o = comb(src, d * tweak, [0.8, 0.79, 0.78, 0.77][i]);
          for (let k = 0; k < sum.length; k++) sum[k] += o[k] * 0.25;
        });
        return allpass(allpass(sum, 0.005 * tweak, 0.7), 0.0017 * tweak, 0.7);
      };
      const delay = (src, time, fb, mix) => {
        const d = Math.floor(time * SR);
        const out = new Float32Array(src.length);
        for (let i = 0; i < src.length; i++) out[i] = src[i] * mix + (i >= d ? out[i - d] * fb : 0);
        return out;
      };
      const beat = 60 / bpm;
      const wetL = reverb(SL, 1.0);
      const wetR = reverb(SR_, 1.13);
      const dL = delay(SR_, beat * 0.75, 0.38, 0.35);
      const dR = delay(SL, beat * 0.75 + 0.01, 0.38, 0.35);
      for (let i = 0; i < N; i++) {
        L[i] += wetL[i] * 0.9 + dL[i] * 0.5;
        R[i] += wetR[i] * 0.9 + dR[i] * 0.5;
      }
      let peak = 0;
      for (let i = 0; i < N; i++) {
        const t = i / SR;
        const g = Math.min(1, t / fadeInSec) * Math.min(1, Math.max(0, (N / SR - t) / fadeOutSec));
        L[i] = Math.tanh(L[i] * 0.9) * g;
        R[i] = Math.tanh(R[i] * 0.9) * g;
        peak = Math.max(peak, Math.abs(L[i]), Math.abs(R[i]));
      }
      const norm = peak > 0 ? peakTarget / peak : 1;
      const pcm = Buffer.alloc(N * 4);
      let clipped = 0;
      for (let i = 0; i < N; i++) {
        const l = Math.max(-1, Math.min(1, L[i] * norm));
        const r = Math.max(-1, Math.min(1, R[i] * norm));
        if (Math.abs(l) >= 1 || Math.abs(r) >= 1) clipped++;
        pcm.writeInt16LE(Math.round(l * 32767), i * 4);
        pcm.writeInt16LE(Math.round(r * 32767), i * 4 + 2);
      }
      const header = Buffer.alloc(44);
      header.write("RIFF", 0);
      header.writeUInt32LE(36 + pcm.length, 4);
      header.write("WAVEfmt ", 8);
      header.writeUInt32LE(16, 16);
      header.writeUInt16LE(1, 20);
      header.writeUInt16LE(2, 22);
      header.writeUInt32LE(SR, 24);
      header.writeUInt32LE(SR * 4, 28);
      header.writeUInt16LE(4, 32);
      header.writeUInt16LE(16, 34);
      header.write("data", 36);
      header.writeUInt32LE(pcm.length, 40);
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, Buffer.concat([header, pcm]));
      return { file, seconds: N / SR, peakBeforeNorm: peak, clipped };
    },
  };
  return api;
}
